import sys,collections
sys.path.insert(0,"engine")
from odata_client import ODataClient
c=ODataClient()
accs={}
for a in c.list("ChartOfAccounts_Хозрасчетный", select=["Ref_Key","Code","Description"]):
    accs[a["Ref_Key"]]=((a.get("Code") or "").strip(),(a.get("Description") or "").strip())
keys=[k for k,(code,d) in accs.items() if code in ("1110","1200")]
vid={v["Ref_Key"]:(v.get("Description") or "").strip() for v in c.list("Catalog_ВидОплаты", select=["Ref_Key","Description"])}
flt=" or ".join("AccountDr_Key eq guid'%s' or AccountCr_Key eq guid'%s'"%(k,k) for k in keys)
rows=list(c.list("AccountingRegister_Хозрасчетный_RecordType", filter=flt))
print("рухів:",len(rows))
def side(r):
    if r.get("AccountDr_Key") in keys: return "Dr "+accs[r["AccountDr_Key"]][0]
    return "Cr "+accs[r["AccountCr_Key"]][0]
print("\nпо рахунку і наявності виду оплати:")
cnt=collections.Counter((side(r), bool(vid.get(r.get("ВидОплаты_Key")))) for r in rows)
for (s,has),n in sorted(cnt.items()): print("   %-10s вид оплати %s : %d"%(s,"є" if has else "НЕМАЄ",n))
nov=[r for r in rows if not vid.get(r.get("ВидОплаты_Key"))]
print("\nчим ідентифікуються рухи БЕЗ виду оплати (поля з різними GUID):")
NULL="00000000-0000-0000-0000-000000000000"
cand=collections.Counter()
for r in nov:
    for k,v in r.items():
        if k.endswith("_Key") and isinstance(v,str) and v not in (NULL,None) and k not in ("AccountDr_Key","AccountCr_Key","ВидОплаты_Key"):
            cand[k]+=1
for k,n in cand.most_common(10): print("   %-32s заповнено в %d з %d"%(k,n,len(nov)))
print("\nперіоди рухів: від",min(r["Period"] for r in rows)[:10],"до",max(r["Period"] for r in rows)[:10])
EOF
